// Playwright config. Tests bind to data-testid only and assert through the UI. The app is already
// running (started by bin/e2e), so no webServer here.
import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
  testDir: './specs',
  use: {
    baseURL: process.env.BASE_URL ?? `http://localhost:${process.env.PORT ?? 3000}`,
    // The contract attribute is data-testid — Playwright's default, so no testIdAttribute override
    // needed. Strict awaiting on data-testid presence is the flake guard.
  },
  // Every spec arranges its own data through the screens on a sheet id of its own and reads the
  // audit file filtered by that id, so specs never share data. workers:1 keeps the suite serial
  // against the one shared app, so a failure stays attributable to one spec.
  fullyParallel: false,
  workers: 1,
  reporter: [['list']],
  projects: [
    {
      name: 'chromium',
      use: {
        ...devices['Desktop Chrome'],
        // Headless Chromium needs its own sandbox off and
        // shared memory in /tmp, or renderer/GPU child processes crash. Harmless elsewhere too.
        launchOptions: { args: ['--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu'] },
      },
    },
  ],
});
export async function setRate(page: Page, f: { grade: string; pct: string; from?: string; to?: string }): Promise<boolean> {
  await page.getByTestId('rate-form-grade').selectOption(f.grade);
  await page.getByTestId('rate-form-pct').fill(f.pct);
  if (f.from !== undefined) await page.getByTestId('rate-form-from').fill(f.from);
  if (f.to !== undefined) await page.getByTestId('rate-form-to').fill(f.to);
  const r = page.getByTestId(`rate-row-${f.grade}-${f.from ?? 'start'}`);
  const done = async () => (await r.count()) > 0 && await shown(r.getByTestId('rate-pct')) === f.pct
    && (f.to === undefined || await shown(r.getByTestId('rate-to')) === f.to);
  const already = await done();
  await page.getByTestId('rate-form-submit').click();
  return until(page, done, page.getByTestId('rate-form-error'), 'set rate', already);
}
export async function userPage(browser: Browser, user: string, sheet: string): Promise<Page> {
  let owner = '';
  try { owner = test.info().testId; } catch { /* outside a test: nothing to tidy by */ }
  for (const [c, t] of opened) {
    if (t === owner) continue;
    opened.delete(c);
    await c.close().catch(() => { /* already gone */ });
  }
  const context = await browser.newContext();
  opened.set(context, owner);
  const page = await context.newPage();
  page.setDefaultTimeout(LOAD_WAIT);     // an element an action needs that never shows fails here, not at the test's limit
  await page.goto('/');
  await page.getByTestId('signin-name').fill(user);
  await page.getByTestId('signin-submit').click();
  await expect(page.getByTestId('current-user')).toHaveText(user, { timeout: LOAD_WAIT });
  await loadSheet(page, sheet);
  return page;
}

